package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestParam;

/** Raises the claim's proofs count by one, of the kind chosen (receipt or photo; receipt when none is chosen); a
 *  SETTLED or VOID claim, or an unknown kind, is refused. */
public class ApplyProof {
    public void apply(@Val Claim claim, ClaimRepository repository,
            @RequestParam(name = "kind", required = false) String kind) throws ClaimStatusException {
        String chosen = kind == null || kind.isBlank() ? null : kind.trim();
        if (chosen != null && !ProofKind.ALL.contains(chosen)) {
            throw new ClaimStatusException("A proof is a receipt or a photo.");
        }
        if (claim.getStatus() == ClaimStatus.SETTLED || claim.getStatus() == ClaimStatus.VOID) {
            throw new ClaimStatusException("A " + claim.getStatus() + " claim cannot gain a proof.");
        }
        claim.addProof(chosen == null ? ProofKind.RECEIPT : chosen);
        repository.saveAndFlush(claim);
    }
}
    public void setHeld(boolean held) {
        this.held = held;
    }

    /** Whether the claim is deferred on a day: it is OPEN and deferred until a date after that day. Until then it counts
     *  in no total, is not overdue, cannot be settled and is left unbound by a statement. */
    public boolean isDeferredOn(LocalDate today) {
        return getStatus() == ClaimStatus.OPEN && deferredUntil != null && deferredUntil.isAfter(today);
    }

    public int getProofs() {
        return proofs;
    }

    /** How many of the claim's proofs are receipts. */
    public int getProofsReceipt() {
        return proofs - proofsPhoto;
    }

    /** How many of the claim's proofs are photos. */
    public int getProofsPhoto() {
        return proofsPhoto;
    }

    /** How many of the claim's proofs are of a kind (receipt or photo). */
    public int proofsOf(String kind) {
        return ProofKind.PHOTO.equals(kind) ? getProofsPhoto() : ProofKind.RECEIPT.equals(kind) ? getProofsReceipt() : 0;
    }

